ContDiffWithinAt.hasFDerivWithinAt_nhds.{uE, uF, uG, u_1} {𝕜 : Type u_1} [NontriviallyNormedField 𝕜] {E : Type uE}
  [NormedAddCommGroup E] [NormedSpace 𝕜 E] {F : Type uF} [NormedAddCommGroup F] [NormedSpace 𝕜 F] {G : Type uG}
  [NormedAddCommGroup G] [NormedSpace 𝕜 G] {s : Set E} {f : E → F → G} {g : E → F} {t : Set F} {n : ℕ} {x₀ : E}
  (hf : ContDiffWithinAt 𝕜 (↑n + 1) (uncurry f) (insert x₀ s ×ˢ t) (x₀, g x₀)) (hg : ContDiffWithinAt 𝕜 (↑n) g s x₀)
  (hgt : t ∈ 𝓝[g '' s] g x₀) :
  ∃ v ∈ 𝓝[insert x₀ s] x₀,
    v ⊆ insert x₀ s ∧
      ∃ f', (∀ x ∈ v, HasFDerivWithinAt (f x) (f' x) t (g x)) ∧ ContDiffWithinAt 𝕜 (↑n) (fun x => f' x) s x₀

